#!/usr/bin/env python3
"""Render a compact, immutable three-way integration report; normal builds are offline."""
from pathlib import Path
import json,hashlib,html,argparse
from evidence_sources import data_root,sources,url
R=Path(__file__).resolve().parents[1];PREFIX='content/integrations/tanstack/source';SHA='c7469b59ba2ccf519ab85ae83485ed3783545a8f';REPO='nift-experiments/nift-tanstack'
p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
root=data_root(PREFIX);source=sources()['files'];load=lambda name:json.loads((root/name).read_text())
a=load('results-phase2.json');c=load('results.json');js=load('javascript.json');parity=load('parity.json');clone=load('clean-clone.json')
assert parity['documents']==3000 and parity['mdx']==979 and parity['islandMounts']==1958 and not parity['failures']
assert clone['allPublicationFilesByteIdentical']['files']==3102 and clone['sourceHashesMatchAllDocuments']==3000
models=[('hybrid','A','Integrated Nift + Start','a'),('control','B','Optimised Start','b'),('nift-first','C','Nift-first islands','c')]
scenarios=['fresh','warm-full','unchanged','docs-edit','shared-layout']
raw={x['scenario']:x for x in a+c};rows={}
for m,_,_,_ in models:
 rows[m]={}
 for case in scenarios:
  x=raw['3000-'+m+'-'+case];assert x['exitCode']==0
  rows[m][case]={'seconds':x['wallSeconds'],'treeMiB':x['sampledTreePeakMiB'],'individualMiB':x['maximumIndividualProcessKiB_time']/1024}
summary={'repo':REPO,'commit':SHA,'samplePolicy':'one serialized observation per case; not medians; earlier Phase 2 cohort is not interleaved with islands','metrics':rows,'javascript':js,'corpus':{'documents':3000,'mdx':979,'originalGuides':62,'islandMounts':1958,'htmlEntries':3089,'cleanPublicationFiles':3102},'sources':[{**source[PREFIX+'/'+name],'alias':PREFIX+'/'+name} for name in ['results-phase2.json','results.json','javascript.json','parity.json','clean-clone.json','REPORT.md','MAINTENANCE.md','BASELINE-62-PAGES.md','environment-phase2.json','references-unchanged.json']]}
captures={x['capture']:x for x in js['captures']}
for model,_,_,_ in models:
 for kind,wanted in [('plain',746 if model=='nift-first' else 395711),('mdx',221084 if model=='nift-first' else 395711)]:
  assert captures['network-'+kind+'-'+model]['jsResponseBytes']==wanted
for model,wanted in [('hybrid',419381),('control',419381),('nift-first',466002)]:assert js['allPublishedJS'][model]['uncompressedBytes']==wanted
assert abs(rows['control']['fresh']['seconds']-23.115033496171236)<1e-9
assert abs(rows['nift-first']['fresh']['seconds']-16.118768016807735)<1e-9
base=f'https://github.com/{REPO}/blob/{SHA}/'
link=lambda path,label:f'<a href="{base+path}">{label} <span aria-hidden="true">↗</span></a>'
def sec(v,case):return f'{v:.3f}' if case=='unchanged' else f'{v:.2f}'
def plot(case,metric,title,limit,unit):
 out=f'<figure class="plot"><figcaption><span>{title}</span><small>{"Wall time" if metric=="seconds" else "Sampled tree RSS"} · lower is better</small></figcaption><div class="axis"><span>0</span><span>{limit:g} {unit}</span></div>'
 for model,letter,label,cls in models:
  v=rows[model][case][metric];assert 0<=v<=limit,(case,metric,v,limit);number=sec(v,case) if metric=='seconds' else f'{v:.1f}'
  out+=f'<div class="bar-row {cls}"><span class="bar-name"><b>{letter}</b>{label}</span><span class="track" aria-hidden="true"><i style="width:{v/limit*100:.5f}%"></i></span><strong>{number}<small> {unit}</small></strong></div>'
 return out+'</figure>'
def section(n,id,title,lede,body):return f'<section class="chapter" id="{id}" aria-labelledby="{id}-title"><div class="chapter-heading"><p class="eyebrow">{n} / {id.replace("-"," ")}</p><h2 id="{id}-title">{title}</h2><p class="section-lede">{lede}</p></div>{body}</section>'
parts=['''<header class="mast"><a class="brand" href="@path('/')">N<span class="brand-mark" aria-hidden="true">/</span> NIFT LABS</a><nav aria-label="Report"><a href="@path('integrations/')">Integrations</a><a href="#architectures">Architectures</a><a href="#measurements">Measurements</a><a href="#evidence">Evidence</a></nav><span class="issue">INTEGRATION / 001</span></header>
<main id="main" class="wrap"><p class="draft"><strong>Integration study / 001</strong> · Independent experiment; no TanStack endorsement.</p>
<section class="hero" aria-labelledby="report-title"><div class="hero-copy"><p class="eyebrow"><span class="port" aria-hidden="true"></span> Greenfield systems / October 2026</p><h1 id="report-title"><span class="word-nift">Nift</span> <span class="plus">+</span> <span class="word-tanstack">TanStack</span></h1><p class="hero-lede"><strong>Nift generates the website.<br>TanStack powers the interactions.</strong> Three architectures and 3,000 documents explore how these responsibilities fit together.</p><div class="hero-links"><a href="#architectures">Trace the architectures <span aria-hidden="true">↓</span></a>'''+link('evaluation/nift-first/REPORT.md','Inspect the original report')+'''</div></div>
<figure class="assembly" aria-labelledby="assembly-caption"><div class="board-label"><span>COMPOSITION / C</span><span>STATIC + SELECTIVE</span></div><div class="module static-module"><span class="module-label">BUILD OWNERSHIP</span><strong>Nift</strong><span>Sources → templates → HTML</span><div class="page-tiles" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div></div><div class="interface"><span aria-hidden="true">↓</span> HTML + explicit mount boundaries <span aria-hidden="true">↓</span></div><div class="module interactive-module"><span class="module-label">INTERACTION OWNERSHIP</span><strong>React + TanStack</strong><span class="library-list">Query · Table · Virtual · Form · Router</span><div class="island-map"><span>Interactive MDX</span><span>Explorer</span><span>CSR workspace</span></div></div><figcaption id="assembly-caption">TanStack libraries provide selective functionality here. TanStack Start owns the complete application in A/B instead.<br>Architecture schematic · not a measured dependency graph.</figcaption></figure></section>
<section class="choice" aria-labelledby="choice-title"><div><p class="eyebrow">The engineering recommendation</p><h2 id="choice-title">Better together.<br>For this workload.</h2></div><div class="choice-copy"><p><strong>For this documentation-heavy website with selective interactivity, we’d choose Nift-first with TanStack islands.</strong> Full publication is faster, peak build memory is lower, and ordinary articles deliver much less JavaScript.</p><p>Adding Nift dependency management to our already optimised Start implementation did not improve this particular workflow. <strong>That does not establish the best full-stack architecture.</strong> We did not evaluate a standalone Nift full-stack application, and these configurations do not provide identical server-side capabilities.</p><p class="qualification">The control still wins unchanged and individual document-edit builds. These are single observations, and the architectures do not provide identical server-side contracts.</p></div></section>''']
parts.append(section('01','architectures','Who owns the page?','The final comparison contains three 3,000-document configurations. An earlier 62-guide prototype explains how we reached them.',
'''<div class="origin-note"><span class="step-id">PRELUDE / 62 GUIDES</span><div><h3>First, Nift beside TanStack.</h3><p>The first prototype gave Nift an independent docs shell beside a Start application. It worked, with cheap documentation updates, but separate HTML/JSX layouts and document-to-app navigation added maintenance seams. For that prototype, the assessment preferred the TanStack-only implementation. This smaller, different workload is preserved; its timings are not mixed into the charts below.</p>'''+link('evaluation/BASELINE-62-PAGES.md','Preserved first experiment')+'''</div></div>
<div class="architecture-grid"><article class="architecture a"><span class="architecture-id" aria-hidden="true">A</span><p class="eyebrow">Integrated Nift + Start</p><h3>One application.<br>An extra planner.</h3><ol class="pipeline"><li>Maintained Markdown / MDX</li><li>Shared bounded compiler</li><li>Nift publishes content payloads</li><li>Start / React renders every page</li><li>One Router, SSR &amp; hydration</li></ol><p>Phase 2 fixed the split-shell boundary. Nift selects dependencies and publishes JSON <em>before</em> Start SSR; it does not replace the expensive React rendering.</p><p class="verdict"><strong>Finding</strong> Functional integration; no compelling advantage over the optimised control.</p></article>
<article class="architecture b"><span class="architecture-id" aria-hidden="true">B</span><p class="eyebrow">Optimised TanStack Start</p><h3>The serious<br>non-Nift control.</h3><ol class="pipeline"><li>The same authored inputs</li><li>The same bounded compiler</li><li>Content-fingerprint planner</li><li>The same Start / React SSR</li><li>The same application &amp; search</li></ol><p>Stable bundles, isolated compilation, bounded workers and stage caches benefit this implementation too. It is not an intentionally expensive control.</p><p class="verdict"><strong>Finding</strong> Best measured unchanged/docs-edit loop; the better measured trade-off of the two Start-based implementations.</p></article>
<article class="architecture c"><span class="architecture-id" aria-hidden="true">C</span><p class="eyebrow">Nift-first + TanStack islands</p><h3>Static ownership.<br>Selective interactivity.</h3><ol class="pipeline"><li>Markdown → HTML directly</li><li>MDX → HTML + island props</li><li>Nift templates compose pages</li><li>React mounts local components</li><li>Router workspace stays bounded</li></ol><p>Query, Table, Virtual and Form power a real explorer. The existing dashboard runs in an embedded Router workspace. Ordinary articles do not hydrate a React document.</p><p class="verdict"><strong>Finding</strong> Our choice for this static-heavy portal; a different application contract.</p></article></div>
<p class="context-note">This is a greenfield PulseOps fixture, not a migration of TanStack.com. That <a href="@path('sites/tanstack/')">separate migration/rewrite investigation</a> retains its own conclusions. <a href="@path('sites/agora/')">Agora Docs</a> remains a production-site migration.</p>'''))
parts.append(section('02','contract','Keep the differences attached.','Equivalent document content and working interactions do not imply an identical application framework contract.',
'''<div class="table-scroll" role="region" aria-label="Architectural capabilities" tabindex="0"><table><caption>Capabilities and ownership</caption><thead><tr><th scope="col">Responsibility</th><th scope="col">A · Integrated</th><th scope="col">B · Optimised Start</th><th scope="col">C · Nift-first</th></tr></thead><tbody>
<tr><th scope="row">Shared page layout</th><td>React / Start</td><td>React / Start</td><td>Nift HTML templates</td></tr>
<tr><th scope="row">Docs ↔ app navigation</th><td>Unified client Router</td><td>Unified client Router</td><td>Full document navigation</td></tr>
<tr><th scope="row">Documentation interactivity</th><td>Whole document hydration</td><td>Whole document hydration</td><td>Local React mounts</td></tr>
<tr><th scope="row">Workspace initial rendering</th><td>Start SSR</td><td>Start SSR</td><td>Client-rendered; JavaScript required</td></tr>
<tr><th scope="row">Server-function lifecycle</th><td>Retained Start</td><td>Retained Start</td><td>Static fixture APIs; not equivalent</td></tr>
<tr><th scope="row">App compilation after docs edit</th><td>Skipped</td><td>Skipped</td><td>Skipped</td></tr>
<tr><th scope="row">Search after content edit</th><td>Full index regeneration</td><td>Full index regeneration</td><td>Full index regeneration</td></tr>
</tbody></table></div>
<div class="proof-strip"><div><strong>3,000</strong><span>source documents checked</span></div><div><strong>979</strong><span>MDX sources retained</span></div><div><strong>1,958</strong><span>local island mount points</span></div><div><strong>3,102</strong><span>byte-identical clean-clone files</span></div></div>
<div class="two-column"><div><h3>Content and behavior before speed.</h3><p>All 3,000 articles retain their heading text/anchors, table-cell content and highlighted code. Search bytes match the unchanged control; every published local link, image and script target resolves. Browser checks exercise authored/generated MDX tabs and calculators, search, dashboard data, deployment filters/details, capacity controls and saved settings.</p><p>A fresh agent fixed Form validation/accessibility from the source map; parent browser checks separately confirmed empty-submit rejection, a stable input label and valid local submission. The API explorer uses real Query loading, Table sorting/filtering and Virtual scrolling—not merely installed packages.</p></div><div><h3>Different inventories, explicit scope.</h3><p>Nift-first emits <strong>3,089 HTML entry pages</strong>, including workspace entry wrappers and the additional explorer. Start configurations emit 3,002 static pages plus runtime application routes. The wrappers are not prerendered dashboards.</p><p>The corpus preserves 62 original guides and expands through deterministic fictional, versioned reference generation. It is <strong>not 3,000 independently authored production articles</strong>. A clean GitHub checkout reproduced all 3,102 publication files byte-for-byte. These are representative functional checks, not certification of every viewport or a production deployment.</p></div></div>'''))
body='<p class="measurement-note"><strong>One observation per case. Not medians.</strong> The earlier Phase 2 cohort is retained unchanged, not interleaved with the islands run. Warm publication reuses valid compilation in every configuration; fresh means fresh application state, not a cold OS cache.</p>'
body+='<div class="plot-grid">'+plot('fresh','seconds','Fresh production build',30,'s')+plot('fresh','treeMiB','Fresh build memory',450,'MiB')+plot('warm-full','seconds','Warm full publication',10,'s')+plot('warm-full','treeMiB','Warm publication memory',300,'MiB')+'</div>'
body+='''<div class="reading"><h3>Changing ownership removes work.</h3><p>Nift-first avoids Start/React rendering for ordinary Markdown and whole-document hydration in the browser. Its fresh observation is about 30% faster than the optimised control, with about 31% lower sampled tree RSS. Warm full publication is about three times faster.</p><p>Markdown uses a standard Markdown/GFM/highlighting pipeline; MDX still uses the official compiler and build-time React static rendering. The final fresh compilation/rendering stage costs <strong>11.99s</strong>. The 979 MDX sources are not free, and these are not native <code>&#64;markup</code> performance results.</p></div>'''
parts.append(section('03','measurements','Full publication gets lighter.','Zero-origin linear bars. Each panel states its own axis maximum; compare configurations within a panel.',body))
body='<p class="measurement-note"><strong>The control wins the small-update cases.</strong> Nift-first still walks/hashes content and body data, prepares recipes and traverses the native graph. A document edit also regenerates the global search index. These fixed costs remain future profiling targets.</p>'
for case,title,limit,memlimit in [('unchanged','Unchanged command',1.5,160),('docs-edit','One document edit',2.5,250),('shared-layout','Shared layout edit',10,450)]:body+='<div class="scenario-board"><h3>'+title+'</h3><div class="plot-grid">'+plot(case,'seconds',title+' · time',limit,'s')+plot(case,'treeMiB',title+' · memory',memlimit,'MiB')+'</div></div>'
body+='''<p class="context-note">Shared layout means a React root-layout change in A/B and the common Nift header in C—equivalent site-wide purpose, different implementation boundaries. Both publish all affected pages. Other diagnostic cases and component costs remain in the pinned source report.</p><details class="numbers"><summary>Complete results and individual-process memory</summary><div class="table-scroll" role="region" aria-label="Complete time and individual RSS observations" tabindex="0"><table><caption>Wall time / maximum individual process or phase RSS. This memory metric is separate from the sampled-tree charts.</caption><thead><tr><th scope="col">Scenario</th><th scope="col">A · Integrated</th><th scope="col">B · Optimised Start</th><th scope="col">C · Nift-first</th></tr></thead><tbody>'''
for case in scenarios:
 body+='<tr><th scope="row">'+case.replace('-',' ')+'</th>'+''.join('<td>'+sec(rows[m][case]['seconds'],case)+'s / '+f"{rows[m][case]['individualMiB']:.1f}"+' MiB</td>' for m,_,_,_ in models)+'</tr>'
body+='</tbody></table></div></details><div class="method-note"><h3>What the memory numbers mean</h3><p>Linux descendant-process RSS is sampled at a 2ms target interval; actual gaps are recorded. The tree peak sums simultaneously resident descendants, can double-count shared pages, and can miss short peaks. It excludes the observer and is neither PSS nor total machine memory. GNU time’s maximum individual-process/phase RSS is retained separately above. No sum of individual maxima is presented as aggregate memory.</p></div>'
parts.append(section('04','iteration','A faster full build is not a faster edit loop.','Time and peak memory stay attached to the same incremental workload.',body))
parts.append(section('05','javascript','Ship interactivity where it is used.','The delivery result is selective loading, not a smaller whole-site asset directory.',
'''<div class="delivery"><div class="delivery-number"><span class="eyebrow">Ordinary Nift-first guide</span><strong>746<span>B</span></strong><span>external JavaScript response bodies</span></div><div><h3>Ordinary HTML does not need React hydration.</h3><p>The static guide loads a tiny vanilla shell for theme and tab-note behavior. Interactive MDX loads React and a component entry. Search loads its own script on the documentation index; the workspace and explorer have separate entries.</p></div></div>
<div class="table-scroll" role="region" aria-label="Browser JavaScript delivery" tabindex="0"><table><caption>Cold browser document navigation · uncompressed external JavaScript response-body bytes</caption><thead><tr><th scope="col">Page</th><th scope="col">A · Integrated</th><th scope="col">B · Optimised Start</th><th scope="col">C · Nift-first</th></tr></thead><tbody><tr><th scope="row">Ordinary guide</th><td>395,711 B</td><td>395,711 B</td><td>746 B</td></tr><tr><th scope="row">Interactive MDX guide</th><td>395,711 B</td><td>395,711 B</td><td>221,084 B</td></tr><tr><th scope="row">All published JavaScript</th><td>419,381 B</td><td>419,381 B</td><td>466,002 B</td></tr></tbody></table></div>
<p class="measurement-note">Including executable inline scripts in HTML, the Start totals are 404,056 B for the ordinary guide and 405,272 B for MDX. Nift-first has no executable inline script on those sampled articles. These are uncompressed response bodies—not compressed network transfer, HTTP/TLS overhead, latency or Web Vitals. The additional Query/Table/Virtual/Form explorer makes Nift-first’s total published JS <strong>larger</strong>; ordinary readers load less of it.</p>'''))
parts.append(section('06','lessons','Choose an architecture for the workload.','The recommendation changed after a different ownership model was tested—not after weakening the control.',
'''<div class="decision-list"><article><span>STATIC / DOCS</span><div><h3>Choose Nift-first for this portal.</h3><p>It is a strong fit when articles dominate and interactive regions are bounded. Faster full publication, lower peak memory and lighter ordinary-page delivery are material here. It does not win unchanged or individual docs edits.</p></div></article><article><span>MIXED / INTERACTIVE</span><div><h3>Choose the boundary deliberately.</h3><p>Nift-first combines islands with a bounded workspace in this implementation. The Start configurations retain continuous Router state, shared query context and SSR across the application. Docs↔app document navigation is a tradeoff here, not an inherent limitation of Nift or a verdict on other architectures.</p></div></article><article><span>FULL STACK</span><div><h3>Full-stack conclusions remain open.</h3><p>Of the two Start-based configurations tested, the optimised control offered the better measured trade-off. This Nift-first implementation deliberately does not reproduce Start’s server-function lifecycle; fixture-backed JSON is not equivalent. We did not compare a standalone Nift full-stack architecture or establish that Start is generally preferable for full-stack development.</p></div></article></div>
<div class="two-column"><div><h3>Shared optimisations remain shared.</h3><p>Isolated MDX compilation, bounded workers, stable bundles and caching helped both Start implementations. They are not exclusive Nift gains. This experiment does not prove that only Nift could implement an efficient static-first site.</p><p>Nift-first lets ordinary authors use Markdown, HTML and CSS. A new interactive MDX component still needs an island entry and an explicit fallback/provider boundary. Its simple development watcher requires a manual reload; it does not match the reference’s React HMR experience.</p></div><div><h3>Keep the weaker results visible.</h3><p>The first islands pass retained the search heap and traversed the graph twice. Correcting those costs helped. A later regression exposed literal-template and failed-intermediate recovery bugs; fixing them added validation cost. The final fresh build is <strong>16.12s</strong>, not the faster pre-fix observation.</p><p>Future work includes cheaper unchanged planning, incremental search, simpler island registration and better development-server integration. Those are future Nift/tooling targets, not reasons to rewrite this result. No Nift core changes were made.</p></div></div>'''))
links=[('evaluation/nift-first/REPORT.md','Three-way engineering report'),('evaluation/results-phase2.json','Integrated + control observations'),('evaluation/nift-first/results.json','Final islands observations'),('evaluation/nift-first/javascript.json','JavaScript delivery and output sizes'),('evaluation/nift-first/parity.json','3,000-document content checks'),('evaluation/nift-first/clean-clone.json','Clean-checkout reproduction'),('evaluation/nift-first/MAINTENANCE.md','Fresh-agent maintenance'),('evaluation/BASELINE-62-PAGES.md','Preserved 62-guide baseline'),('evaluation/environment-phase2.json','Host and pinned environment'),('evaluation/nift-first/references-unchanged.json','Reference preservation check'),('evaluation/nift-first/initial-pass/','Initial profiling observations'),('evaluation/nift-first/pre-recovery-pass/','Pre-recovery observations'),('nift-first/README.md','Build and source ownership guide')]
parts.append(section('07','evidence','Follow the result back to source.','Canonical evidence stays in the experiment repository. Labs keeps only this compact displayed summary.',
'<div class="evidence-grid">'+''.join(link(path,label) for path,label in links)+'''</div><div class="source-stamp"><span>PINNED EXPERIMENT</span><a href="https://github.com/nift-experiments/nift-tanstack/tree/'''+SHA+'">nift-experiments/nift-tanstack · c7469b5 ↗</a></div><p>The separate clean clone reproduced all <strong>3,102 publication files byte-for-byte</strong>. Both earlier reference implementations and their reports remain unchanged. Hash-verified source pointers are recorded in the Labs evidence index; normal site builds need no network or experiment checkout.</p><p class="qualification">Independent greenfield research. Generated fixture corpus. Single observations. Different application contracts. Representative browser checks. No production deployment certification or TanStack endorsement.</p>'))
parts.append('''</main><footer class="report-footer wrap"><a href="@path('integrations/')">← All integrations</a><span>Nift Labs / experiments in the open</span><a href="https://github.com/nift-experiments/nift-tanstack">Repository ↗</a></footer>''')
outputs={R/'content/integrations/tanstack/data/published.json':json.dumps(summary,indent=2)+'\n',R/'content/integrations/tanstack/index.html':'\n'.join(parts)+'\n'}
for path,text in outputs.items():
 if args.check:assert path.read_text()==text,'Stale generated report: '+str(path)
 else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text)
print('TanStack integration: 15 matched scenario cells + JS, parity and clone gates verified; '+('current' if args.check else 'rendered'))
